import{_ as a,o as i,c as e,a0 as p}from"./chunks/framework.IrjkP_YN.js";const k=JSON.parse('{"title":"2 核 4G 的机器上 Milvus 被 OOM 杀掉，我是怎么查到的","description":"","frontmatter":{},"headers":[],"relativePath":"posts/oom.md","filePath":"posts/oom.md","lastUpdated":null}'),t={name:"posts/oom.md"};function o(n,s,l,h,r,d){return i(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_2-核-4g-的机器上-milvus-被-oom-杀掉-我是怎么查到的" tabindex="-1">2 核 4G 的机器上 Milvus 被 OOM 杀掉，我是怎么查到的 <a class="header-anchor" href="#_2-核-4g-的机器上-milvus-被-oom-杀掉-我是怎么查到的" aria-label="Permalink to &quot;2 核 4G 的机器上 Milvus 被 OOM 杀掉，我是怎么查到的&quot;">​</a></h1><p>2026-09</p><h2 id="第一次挂的时候-我以为我修好了" tabindex="-1">第一次挂的时候，我以为我修好了 <a class="header-anchor" href="#第一次挂的时候-我以为我修好了" aria-label="Permalink to &quot;第一次挂的时候，我以为我修好了&quot;">​</a></h2><p>我的服务器是阿里云 2 核 4G，上面跑六个容器：MySQL、etcd、MinIO、Milvus、后端、前端。平时 <code>docker stats</code> 一看，基线占用就 2.1G 左右，Milvus 最大，八九百兆。</p><p>内存一直挺紧的，但能跑。</p><p>然后有一天网站打不开了。<code>free -h</code> 一看，内存快满了。我当时的判断特别快：<strong>内存不够，加 Swap。</strong></p><p>加了 Swap，重启，网站活了。我就以为这事完了。</p><h2 id="_9-月-2-号它又挂了" tabindex="-1">9 月 2 号它又挂了 <a class="header-anchor" href="#_9-月-2-号它又挂了" aria-label="Permalink to &quot;9 月 2 号它又挂了&quot;">​</a></h2><p>这次的现象更怪。</p><p><code>free -h</code> 显示内存只剩 <strong>94M</strong>，而我加的 Swap 有 8G——<strong>用量是 0</strong>。</p><p>一整块备胎挂在那儿，一点没动。</p><p>系统已经半瘫了，<code>docker ps</code> 敲下去卡住不返回。我重启了 ECS，六个容器靠 <code>restart: unless-stopped</code> 自己拉起来了，网站恢复。</p><p>但这次我没敢直接收工，因为「加了 Swap 却没用上」这件事说不通。</p><h2 id="四条证据" tabindex="-1">四条证据 <a class="header-anchor" href="#四条证据" aria-label="Permalink to &quot;四条证据&quot;">​</a></h2><p><strong>一、<code>free -h</code></strong>：内存将满 + Swap 用量 0。备胎存在但没被用，这不是「Swap 不够」，是「根本没打算用 Swap」。</p><p><strong>二、<code>cat /proc/sys/vm/swappiness</code></strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0</span></span></code></pre></div><p>看到这个数字我愣了一下。swappiness 是 0 到 100 的一个开关，表示内核「愿不愿意用 Swap」。<strong>0 的意思是：宁可杀进程，也绝不动 Swap。</strong></p><p><strong>三、<code>journalctl -k -b -1 | grep -i -E &quot;oom|kill&quot;</code></strong></p><p><code>-b -1</code> 是上一次启动的日志（因为 OOM 发生在我重启之前）。日志里实锤了：OOM killer 杀掉了 milvus，当时它占 <strong>1.68G</strong>。</p><p><strong>四、<code>docker ps</code> 佐证</strong>：Milvus 显示 Up 8 分钟，其他容器 Up 10 分钟。</p><p>差的那两分钟就是它被杀掉之后自动重启的时间。这条不是必需的，但它跟第三条对上了，我就知道没查错。</p><h2 id="为什么阿里云要设成-0" tabindex="-1">为什么阿里云要设成 0 <a class="header-anchor" href="#为什么阿里云要设成-0" aria-label="Permalink to &quot;为什么阿里云要设成 0&quot;">​</a></h2><p>查完我特意去看了下，是 <code>/etc/sysctl.d/99-apsara-sysctl.conf</code> 里写的，阿里云自己塞的默认配置。</p><p>想明白之后觉得也合理：<strong>云厂商假设你要极致性能，宁可杀进程也不让你卡。</strong> Swap 是拿磁盘当内存，一旦用上，延迟会难看。对大厂那种机器，这个取舍是对的。</p><p>但我这是 2 核 4G 跑六个容器的玩具机。我要的不是极致性能，是<strong>别死</strong>。</p><p>所以小机器上这个参数得自己改回来。60 是 Ubuntu 的默认值。</p><h2 id="改的时候有个小讲究" tabindex="-1">改的时候有个小讲究 <a class="header-anchor" href="#改的时候有个小讲究" aria-label="Permalink to &quot;改的时候有个小讲究&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sysctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm.swappiness=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 立即生效</span></span></code></pre></div><p>然后写进 <code>/etc/sysctl.conf</code> 让它重启后还在。</p><p>我一开始想去直接改 <code>/etc/sysctl.d/99-apsara-sysctl.conf</code>，后来没动。两个原因：那是厂商自动写的，系统更新可能给我重置回去；而且 <code>/etc/sysctl.conf</code> 的优先级更高，能稳稳盖住它。</p><p>改完再 <code>free -h</code>，Swap 有用量了。<strong>这次我看到 Swap 被用，反而是好事</strong>——说明备胎真的开始工作了。</p><h2 id="我学到的其实不是-swappiness" tabindex="-1">我学到的其实不是 swappiness <a class="header-anchor" href="#我学到的其实不是-swappiness" aria-label="Permalink to &quot;我学到的其实不是 swappiness&quot;">​</a></h2><p>是这个：</p><p><strong>第一次我加了 Swap，网站好了，我就以为修好了。我从头到尾没验证过 Swap 到底有没有被用上。</strong></p><p>如果我当时多敲一句 <code>free -h</code> 看一眼 Swap 用量，就会发现它一直是 0，问题当天就能定位。</p><p>这跟我写代码那个毛病是一模一样的。我写过 <code>try/except</code> 就以为异常被处理了，写过 <code>logger.error(&quot;超时&quot;)</code> 就以为超时被兜住了，设过 <code>tool_choice=&#39;required&#39;</code> 就以为强制生效了。<strong>写了 ≠ 生效，加了 ≠ 用上。</strong></p><p>后来我给自己定了条规矩：改完一个东西，验收标准必须是「我去把结果查出来、眼睛看见了」，不是「它没报错」。</p><p>这条规矩后来救过我好几次，比如有一次导入脚本退出码是 0，我以为插进去了，去库里一查——0 行。</p><h2 id="一些我到现在也没完全搞明白的" tabindex="-1">一些我到现在也没完全搞明白的 <a class="header-anchor" href="#一些我到现在也没完全搞明白的" aria-label="Permalink to &quot;一些我到现在也没完全搞明白的&quot;">​</a></h2><ul><li><code>journalctl -k</code> 和 <code>dmesg</code> 的区别，我讲不清楚。我只知道 <code>-k</code> 是只看内核日志，<code>-b -1</code> 是上一次启动</li><li>OOM killer 挑进程杀的规则，我知道是看内存占用（所以每次死的都是 Milvus），但那个 oom_score 具体怎么算的，我没研究</li><li>Swap 用多了会不会拖慢 Milvus 的查询，我没测过。现在的状态是「偶尔用一点」，我觉得能接受，但这是感觉不是数据</li></ul><hr><p>命令备忘，下次再挂直接用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">free</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                        # 内存和 Swap 各用了多少</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/sys/vm/swappiness</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # 内核愿不愿意用 Swap</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;oom|kill&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 上一次启动里谁被杀了</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stats</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-stream</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                        # 各容器占用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       # 谁活着，Up 多久（能看出谁重启过）</span></span></code></pre></div>`,44)])])}const g=a(t,[["render",o]]);export{k as __pageData,g as default};
